function buildAmenitiesConfig() {
    const amenities = getAllAmenities();
    const groupToCameraName = buildGroupToCameraName();
    const { grouped, ungrouped, nameToAmenity, groupToAmenities, cameraToAmenities } = categorizeAmenities(amenities);
    const normalizedGrouped = grouped.map((group)=>{
        if (isSingleCameraGroup(group)) return group;
        return splitGroupByCamera(group);
    });
    let amenityConfig = [];
    if (ungrouped.length === 0) {
        amenityConfig = [
            ...normalizedGrouped
        ];
    }
    const groupsPerUngrouped = Math.floor(normalizedGrouped.length / (ungrouped.length + 1));
    let groupIndex = 0;
    ungrouped.forEach((item, i)=>{
        const isLastItem = i === ungrouped.length - 1;
        const groupsToAdd = isLastItem ? normalizedGrouped.length - groupIndex : groupsPerUngrouped;
        for(let j = 0; j < groupsToAdd && groupIndex < normalizedGrouped.length; j++){
            amenityConfig.push(normalizedGrouped[groupIndex++]);
        }
        amenityConfig.push(item);
    });
    while(groupIndex < normalizedGrouped.length){
        amenityConfig.push(normalizedGrouped[groupIndex++]);
    }
    return {
        amenityConfig,
        nameToAmenity,
        groupToAmenities,
        cameraToAmenities,
        groupToCameraName
    };
}
const { amenityConfig, nameToAmenity, groupToAmenities, cameraToAmenities, groupToCameraName } = buildAmenitiesConfig();

